      "terminal",
      "file",
      "browser",
      "code_execution",
      "delegation",
      "skills",
      "web",
      "cronjob"
    ]
  },
  "auxiliary": {
    "compression": {
      "model": "example-model",
      "provider": "main"
    },
    "vision": {
      "model": "example-model",
      "provider": "main"
    },
    "web_extract": {
      "model": "example-model",
      "provider": "main"
    }
  },
  "gateway": {
    "multiplex_profiles": false,
    "unauthorized_dm_behavior": "ignore"
  },
  "memory": {
    "memory_enabled": true,
    "user_profile_enabled": true
  },
  "model": {
    "api_mode": "chat_completions",
    "base_url": "https://models.example.org/v1",
    "default": "example-model",
    "provider": "custom"
  },
  "platform_toolsets": {
    "api_server": [
      "memory",
      "session_search",
      "todo"
    ],
    "cron": [
      "memory",
      "session_search",
      "todo"
    ],
    "discord": [
      "memory",
      "session_search",
      "todo"
    ],
    "telegram": [
      "memory",
      "session_search",
      "todo"
    ]
  },
  "platforms": {
    "api_server": {
      "enabled": true,
      "extra": {
        "host": "0.0.0.0",
        "port": 8642
      }
    },
    "discord": {
      "enabled": true
    },
    "telegram": {
      "enabled": true
    }
  },
  "security": {
    "allow_lazy_installs": false,
    "redact_secrets": true
  }
}

agents/openclaw/openclaw.json:
{
  "agents": {
    "defaults": {
      "memorySearch": {
        "enabled": false
      },
      "model": {
        "primary": "lab/example-model"
      },
      "workspace": "/home/node/.openclaw/workspace"
    },
    "entries": {
      "assistant": {
        "name": "assistant"
      }
    }
  },
  "channels": {
    "discord": {
      "allowFrom": [
        "789012"
      ],
      "dmPolicy": "allowlist",
      "enabled": true,
      "groupPolicy": "disabled",
      "token": "${DISCORD_BOT_TOKEN}"
    },
    "telegram": {
      "allowFrom": [
        "123456"
      ],
      "botToken": "${TELEGRAM_BOT_TOKEN}",
      "dmPolicy": "allowlist",
      "enabled": true,
      "groupPolicy": "disabled"
    }
  },
  "commands": {
    "bash": false,
    "config": false,
    "debug": false,
    "nativeSkills": false,
    "restart": false
  },
  "discovery": {
    "mdns": {
      "mode": "off"
    }
  },
  "gateway": {
    "auth": {
      "mode": "token",
      "token": "${AGENT_API_KEY}"
    },
    "bind": "lan",
    "controlUi": {
      "enabled": false
    },
    "http": {
      "endpoints": {
        "chatCompletions": {
          "enabled": true
        }
      }
    },
    "mode": "local",
    "port": 18789
  },
  "logging": {
    "redactSensitive": "tools"
  },
  "models": {
    "mode": "merge",
    "providers": {
      "lab": {
        "api": "openai-completions",
        "apiKey": "${LLM_API_KEY}",
        "baseUrl": "https://models.example.org/v1",
        "models": [
          {
            "id": "example-model",
            "name": "example-model"
          }
        ]
      }
    }
  },
  "tools": {
    "allow": [
      "session_status",
      "memory_get"
    ],
    "deny": [
      "group:runtime",
      "group:fs",
      "group:ui",
      "group:nodes",
      "group:automation",
      "sessions_spawn",
      "subagents"
    ]
  }
}

ansible/roles/agents/tasks/main.json:
[
  {
    "ansible.builtin.package": {
      "name": [
        "docker.io",
        "docker-compose"
      ],
      "state": "present",
      "update_cache": true
    },
    "name": "Install agent container engine"
  },
  {
    "ansible.builtin.systemd": {
      "enabled": true,
      "name": "docker",
      "state": "started"
    },
    "name": "Start agent container engine"
  },
  {
    "ansible.builtin.copy": {
      "dest": "/opt/bromigos-agents/",
      "directory_mode": "0755",
      "mode": "0644",
      "src": "{{ playbook_dir }}/../../agents/"
    },
    "name": "Copy reviewed agent settings"
  },
  {
    "ansible.builtin.shell": {
      "chdir": "/opt/bromigos-agents",
      "cmd": "if docker compose version >/dev/null 2>&1; then docker compose -p bromigos-agents up -d; else docker-compose -p bromigos-agents up -d; fi"
    },
    "changed_when": false,
    "name": "Converge agents without removing volumes"
  }
]
